// Parse the incoming chat message to extract optional date overrides.
// Users can write things like: "show me data from 2026-01-01 to 2026-03-31"
// Otherwise we default to the last 90 days.

const chatInput = $input.first().json.chatInput || '';

const datePattern = /(\d{4}-\d{2}-\d{2})/g;
const foundDates = chatInput.match(datePattern) || [];

const today = new Date();
const ninetyDaysAgo = new Date(today);
ninetyDaysAgo.setDate(today.getDate() - 90);

const dateRangeStart = foundDates[0] || ninetyDaysAgo.toISOString().split('T')[0];
const dateRangeEnd   = foundDates[1] || today.toISOString().split('T')[0];

return [{
  json: {
    chatInput,
    dateRangeStart,
    dateRangeEnd,
    tableName: 'financial_transactions'
  }
}];

const aggregates = $('Supabase - Daily Aggregates').all().map(i => i.json);
const categories  = $('Supabase - Category Breakdown').all().map(i => i.json);
const trends      = $('Supabase - Monthly Trends').all().map(i => i.json);
const parsed      = $('Parse Chat Input').first().json;

// Linear regression over monthly totals
function linearRegression(rows) {
  const n = rows.length;
  if (n < 2) return { slope: 0, intercept: parseFloat(rows[0]?.monthly_total || 0), r2: 0 };
  const y = rows.map(r => parseFloat(r.monthly_total) || 0);
  const x = y.map((_, i) => i);
  const xm = x.reduce((a, b) => a + b, 0) / n;
  const ym = y.reduce((a, b) => a + b, 0) / n;
  const num = x.reduce((s, xi, i) => s + (xi - xm) * (y[i] - ym), 0);
  const den = x.reduce((s, xi) => s + (xi - xm) ** 2, 0);
  const slope = den ? num / den : 0;
  const intercept = ym - slope * xm;
  const ssRes = y.reduce((s, yi, i) => s + (yi - (slope * i + intercept)) ** 2, 0);
  const ssTot = y.reduce((s, yi) => s + (yi - ym) ** 2, 0);
  const r2 = ssTot ? 1 - ssRes / ssTot : 1;
  return {
    slope:     Math.round(slope * 100) / 100,
    intercept: Math.round(intercept * 100) / 100,
    r2:        Math.round(r2 * 1000) / 1000
  };
}

const reg = linearRegression(trends);
const predict = (n) => Math.round((reg.slope * n + reg.intercept) * 100) / 100;

// Anomaly detection: categories > 2 std-dev from mean spend
const amounts = categories.map(c => parseFloat(c.total_amount) || 0);
const mean    = amounts.reduce((a, b) => a + b, 0) / (amounts.length || 1);
const stddev  = Math.sqrt(amounts.reduce((s, v) => s + (v - mean) ** 2, 0) / (amounts.length || 1));
const anomalies = categories
  .filter(c => Math.abs(parseFloat(c.total_amount) - mean) > 2 * stddev)
  .map(c => ({ category: c.category, amount: parseFloat(c.total_amount) }));

const last = trends[trends.length - 1];
const trendDir = (last?.mom_pct_change ?? 0) > 0 ? 'upward'
               : (last?.mom_pct_change ?? 0) < 0 ? 'downward' : 'stable';

const totalAmount = Math.round(
  aggregates.reduce((s, r) => s + parseFloat(r.total_amount || 0), 0) * 100
) / 100;

return [{
  json: {
    chatInput:   parsed.chatInput,
    dateRangeStart: parsed.dateRangeStart,
    dateRangeEnd:   parsed.dateRangeEnd,
    aggregates,
    categories,
    trends,
    analysis: {
      totalTransactions: aggregates.reduce((s, r) => s + parseInt(r.transaction_count || 0), 0),
      totalAmount,
      topCategory:       categories[0]?.category || 'N/A',
      topCategoryAmount: parseFloat(categories[0]?.total_amount || 0),
      trendDirection:    trendDir,
      latestMoMGrowth:   parseFloat(last?.mom_pct_change || 0),
      anomalies,
      regression: reg,
      predictions: {
        nextMonth:    predict(trends.length),
        twoMonthsOut: predict(trends.length + 1)
      }
    }
  }
}];

