const reportContent = $input.first().json.message.content;
const analysis     = $('Compute Analysis & Predictions').first().json.analysis;
const parsed       = $('Parse Chat Input').first().json;
const reportId     = 'RPT-' + Date.now();
const generatedAt  = new Date().toISOString();

return [{
  json: {
    reportId,
    generatedAt,
    chatInput:      parsed.chatInput,
    dateRangeStart: parsed.dateRangeStart,
    dateRangeEnd:   parsed.dateRangeEnd,
    reportContent,
    analysisSummary: analysis
  }
}];

// The Chat Trigger returns the last node's output text as the chat reply.
// We surface the Markdown report as the chat message.
const report = $('Format Report Output').first().json;
return [{
  json: {
    output: report.reportContent
  }
}];
